async def get_label(page: "Page", element: "ElementHandle") -> str:
    """
    Get label text for a form element.

    Tries multiple strategies in order:
    1. Label element with matching 'for' attribute
    2. aria-label attribute
    3. placeholder attribute

    Returns empty string if no label found.
    """
    try:
        el_id = await element.get_attribute("id")
        if el_id:
            label_el = await page.query_selector(f"label[for='{el_id}']")
            if label_el:
                return (await label_el.inner_text()).strip()
        aria = await element.get_attribute("aria-label")
        if aria:
            return aria.strip()
        placeholder = await element.get_attribute("placeholder")
        if placeholder:
            return placeholder.strip()
    except Exception:
        pass
    return ""
